create table ai_conversations (created_at timestamp(6) with time zone not null, ended_at timestamp(6) with time zone, started_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, user_id uuid, primary key (id));
create table ai_messages (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, conversation_id uuid, id uuid not null, content varchar(255), role varchar(255) check ((role in ('USER','ASSISTANT','TOOL'))), tool_calls varchar(255), primary key (id));
create table audit_logs (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, actor_user_id uuid, entity_id uuid, id uuid not null, action varchar(255), entity_type varchar(255), metadata varchar(255), primary key (id));
create table categories (is_active boolean not null, requires_safety_cert boolean not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, parent_id uuid, name varchar(100) not null, name_en varchar(100), slug varchar(120) not null unique, icon_url TEXT, primary key (id));
create table conversations (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, customer_id uuid, id uuid not null, master_order_id uuid, vendor_id uuid, primary key (id));
create table discount_codes (discount_value numeric(38,2), is_active boolean, max_uses integer, used_count integer, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, valid_from timestamp(6) with time zone, valid_to timestamp(6) with time zone, id uuid not null, vendor_id uuid, code varchar(255), discount_type varchar(255) check ((discount_type in ('PERCENTAGE','FIXED'))), scope varchar(255) check ((scope in ('PLATFORM','VENDOR'))), primary key (id));
create table discount_redemptions (amount_deducted numeric(38,2), created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, discount_code_id uuid, id uuid not null, master_order_id uuid, primary key (id));
create table dispute_attachments (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, dispute_id uuid, id uuid not null, file_url varchar(255), primary key (id));
create table disputes (created_at timestamp(6) with time zone not null, resolved_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, raised_by uuid, resolved_by uuid, sub_order_id uuid, category varchar(255), description varchar(255), resolution_note varchar(255), status varchar(255) check ((status in ('OPEN','IN_REVIEW','RESOLVED','REJECTED'))), primary key (id));
create table invoices (created_at timestamp(6) with time zone not null, issued_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, master_order_id uuid, invoice_number varchar(255), pdf_url varchar(255), primary key (id));
create table master_orders (discount_amount numeric(38,2), total_amount numeric(38,2), created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, customer_id uuid, discount_code_id uuid, id uuid not null, status varchar(255) check ((status in ('PENDING_PAYMENT','PAID','PARTIALLY_COMPLETED','COMPLETED','CANCELLED'))), primary key (id));
create table messages (is_read boolean, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, conversation_id uuid, id uuid not null, sender_id uuid, attachment_url varchar(255), content varchar(255), primary key (id));
create table notifications (created_at timestamp(6) with time zone not null, sent_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, related_entity_id uuid, user_id uuid, body varchar(255), channel varchar(255) check ((channel in ('EMAIL','SMS','TELEGRAM','IN_APP'))), related_entity_type varchar(255), status varchar(255) check ((status in ('PENDING','SENT','FAILED'))), title varchar(255), type varchar(255), primary key (id));
create table password_reset_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, used_at timestamp(6) with time zone, id uuid not null, user_id uuid, token_hash varchar(255), primary key (id));
create table payments (amount numeric(38,2), created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, master_order_id uuid, provider varchar(255) check ((provider in ('VNPAY','MOMO','SEPAY'))), provider_transaction_id varchar(255), raw_webhook_payload varchar(255), status varchar(255) check ((status in ('PENDING','SUCCESS','FAILED','REFUNDED'))), primary key (id));
create table payout_requests (amount numeric(38,2), created_at timestamp(6) with time zone not null, processed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, processed_by uuid, settlement_id uuid, vendor_id uuid, status varchar(255) check ((status in ('REQUESTED','APPROVED','PAID','REJECTED'))), primary key (id));
create table recently_vieweds (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, viewed_at timestamp(6) with time zone, id uuid not null, service_id uuid, user_id uuid, session_id varchar(255), primary key (id));
create table refresh_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, revoked_at timestamp(6) with time zone, family_id uuid not null, id uuid not null, replaced_by_id uuid, user_id uuid not null, token_hash varchar(255) not null unique, primary key (id));
create table refunds (amount numeric(38,2), refund_percentage numeric(38,2), created_at timestamp(6) with time zone not null, processed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, sub_order_id uuid, reason varchar(255) check ((reason in ('CUSTOMER_CANCEL','WEATHER','DISPUTE','COMPENSATION'))), status varchar(255) check ((status in ('PENDING','PROCESSED','FAILED'))), primary key (id));
create table reviews (is_flagged boolean, rating smallint, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, vendor_replied_at timestamp(6) with time zone, customer_id uuid, id uuid not null, service_id uuid, sub_order_id uuid, vendor_id uuid, comment varchar(255), images varchar(255), vendor_reply varchar(255), primary key (id));
create table safety_rule_evaluations (is_safe boolean, created_at timestamp(6) with time zone not null, evaluated_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, service_id uuid, slot_id uuid, warning_message varchar(255), primary key (id));
create table service_images (sort_order smallint, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, service_id uuid, url varchar(255), primary key (id));
create table service_safety_documents (created_at timestamp(6) with time zone not null, reviewed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, reviewed_by uuid, service_id uuid, file_url varchar(255), rejection_reason varchar(255), status varchar(255) check ((status in ('PENDING','APPROVED','REJECTED'))), primary key (id));
create table service_slots (booked_count integer, capacity integer, date date, end_time time(0), start_time time(0), created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, service_id uuid, status varchar(255) check ((status in ('OPEN','CLOSED','BLOCKED'))), primary key (id));
create table services (avg_rating numeric(38,2), capacity_per_slot integer, duration_minutes integer, latitude numeric(38,2), longitude numeric(38,2), max_wavem numeric(38,2), min_wind_kmh numeric(38,2), price numeric(38,2), rating_count integer, view_count integer, weather_sensitive boolean, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, category_id uuid, id uuid not null, vendor_id uuid, address varchar(255), description varchar(255), description_en varchar(255), location_name varchar(255), name varchar(255), name_en varchar(255), rejection_reason varchar(255), slug varchar(255), status varchar(255) check ((status in ('DRAFT','PENDING_REVIEW','PUBLISHED','REJECTED','PAUSED'))), waiver_content varchar(255), primary key (id));
create table settlement_items (amount numeric(38,2), created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, settlement_id uuid, sub_order_id uuid, primary key (id));
create table settlements (commission_amount numeric(38,2), gross_amount numeric(38,2), net_payable_amount numeric(38,2), period_end date, period_start date, created_at timestamp(6) with time zone not null, generated_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, vendor_id uuid, status varchar(255) check ((status in ('PENDING','PAID'))), primary key (id));
create table sub_orders (commission_amount numeric(38,2), commission_rate numeric(38,2), quantity integer, subtotal_amount numeric(38,2), unit_price numeric(38,2), vendor_payout_amount numeric(38,2), waiver_accepted boolean, checked_in_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, waiver_accepted_at timestamp(6) with time zone, id uuid not null, master_order_id uuid, qr_secret uuid, service_id uuid, slot_id uuid, vendor_id uuid, status varchar(255) check ((status in ('PENDING','CONFIRMED','REJECTED','COMPLETED','CANCELLED','REFUNDED'))), primary key (id));
create table system_configs (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, updated_by uuid, description varchar(255), "key" varchar(255), "value" varchar(255), primary key (id));
create table users (is_email_verified boolean, is_locked boolean, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, avatar_url varchar(255), email varchar(255), full_name varchar(255), locale varchar(255), password_hash varchar(255), phone varchar(255), role varchar(255) check ((role in ('CUSTOMER','VENDOR','ADMIN'))), primary key (id));
create table vendor_documents (created_at timestamp(6) with time zone not null, reviewed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, reviewed_by uuid, vendor_id uuid, doc_type varchar(255) check ((doc_type in ('BUSINESS_LICENSE','SAFETY_CERT'))), file_url varchar(255), status varchar(255) check ((status in ('PENDING','APPROVED','REJECTED'))), primary key (id));
create table vendors (rating_avg numeric(38,2), rating_count integer, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, verified_at timestamp(6) with time zone, id uuid not null, user_id uuid, verified_by uuid, address varchar(255), badge_tier varchar(255) check ((badge_tier in ('NONE','VERIFIED','TOP_RATED'))), bank_account_holder varchar(255), bank_account_number varchar(255), bank_name varchar(255), business_name varchar(255), tax_code varchar(255), verification_status varchar(255) check ((verification_status in ('PENDING','APPROVED','REJECTED'))), primary key (id));
create table weather_caches (precipitation_mm numeric(38,2), wave_heightm numeric(38,2), wind_speed_kmh numeric(38,2), created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone, fetched_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, location_key varchar(255), raw_payload varchar(255), primary key (id));
create table wishlists (created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, service_id uuid, user_id uuid, primary key (id));
